type Fetch =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; error: Error };

function render(s: Fetch) {
  switch (s.status) {
    case "loading": return "…";
    case "success": return s.data;
    case "error": return s.error.message;
    default: s satisfies never; // 新增状态未处理时这里报错
  }
}

examples.0.body.en:
type Fetch =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; error: Error };

function render(s: Fetch) {
  switch (s.status) {
    case "loading": return "...";
    case "success": return s.data;
    case "error": return s.error.message;
    default: s satisfies never; // errors here when a new state is unhandled
  }
}
